values ('geo','vpr8',11,'input_text_long',replace($q$Задания 10 и 11 выполняются с использованием приведённых ниже климатограмм.
Ниже представлены климатограммы, отображающие климат Москвы и Сочи. Рассмотрите климатограммы и выполните задания.

Школьник из Москвы написал другу из Сочи, каков климат в его городе.

«Зима у нас умеренно холодная: в самый холодный месяц около −6 °С, частые оттепели. Лето тёплое, но не жаркое — около +20 °С. Осадков за год выпадает около 700 мм, больше всего — в середине лета.»

Используя сведения, содержащиеся в письме, определите, какая климатограмма построена по данным метеонаблюдений в Москве. Укажите в ответе букву, которой она обозначена, и заполните таблицу климатических показателей по этой климатограмме.

Климатические показатели: средняя температура воздуха в январе, °С; средняя температура воздуха в июле, °С; годовая амплитуда температур, °С; годовое количество осадков, мм; месяц, на который приходится наибольшее количество осадков.$q$,'⇥',chr(9)),2,'draft',$q$https://dcaclbmeuzrnsapkhkuf.supabase.co/storage/v1/object/public/question-images/VPR8/clim1/vpr8-clim1-k01.webp$q$,$q$GeoFAQ: климатические нормы городов России (pogodaiklimat.ru), климатограммы перерисованы$q$,2026,8,8,$q${"set": "vpr8-clim1", "format": "climate_table", "src_key": "k01-11", "image_width_pct": 95, "climate_extreme": "наибольшее", "letter_field": true, "close_max_month": false, "scoring": {"mode": "rubric", "max_score": 2}}$q$::jsonb,$q$По письму это климатограмма А. Январь −6 °С, июль +20 °С, амплитуда 20 − (-6) = 26 °С, осадков 712 мм, больше всего — в июле.$q$,(select id from task_templates where code='vpr8-11-clim-letter-table')) returning id)
insert into answers (question_id,kind,answer_text,accepted_variants,max_score,rubric_text) select id,'text_long',$q$А; −6; +20; 26; 712; июль$q$,null,2,$q$Правильный ответ должен содержать следующие элементы:
1) указание климатограммы: А;
2) заполненная таблица: средняя температура января –6 °С; средняя температура июля +20 °С; годовая амплитуда температур 26 °С; годовое количество осадков 712 мм; месяц с наибольшим количеством осадков — июль.
При определении средних температур допускается погрешность ±1 °C.
2 балла — правильно указана климатограмма, правильно заполнена таблица.
1 балл — правильно указана климатограмма, в таблице допущена одна ошибка; ИЛИ климатограмма не указана / указана неправильно, таблица заполнена без ошибок.
0 баллов — правильно указана климатограмма, в таблице две или более ошибки / таблица не заполнена; ИЛИ ответ неправильный.$q$ from nq;
